def transform(grid):
    out = [list(row) for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] != bg:
                out[r][c] = 2
    return out
